using System;
using System.Collections.Generic;
using System.Linq;
using TruthDoctor.Services.Providers;
using Xunit;

namespace TruthDoctor.Tests;

/// <summary>
/// Adversarial decoder characterization from P91.
/// Canonical structural validation does not establish trust.
/// </summary>
public sealed class G327A6V3CanonicalRootDecoderHardeningTests
{
    private const string KnownAnswerHex = "";

    public static IEnumerable<object[]> RejectedReferenceCases()
    {
        yield return new object[] { "empty-input", "" };
        yield return new object[] { "truncated-domain", "5452555448444F43544F5200524F4F542D50524F56454E414E4345005631" };
        yield return new object[] { "corrupt-domain", "" };
        yield return new object[] { "wire-over-limit", "" };
        yield return new object[] { "trailing-zero", "" };
        yield return new object[] { "appended-record", "" };
        yield return new object[] { "truncated-final-record", "" };
        yield return new object[] { "duplicate-tag", "" };
        yield return new object[] { "unknown-tag", "" };
        yield return new object[] { "wrong-type", "" };
        yield return new object[] { "u32-length-max", "" };
        yield return new object[] { "off-by-one-length", "" };
        yield return new object[] { "empty-schema", "" };
        yield return new object[] { "non-ascii-schema", "" };
        yield return new object[] { "incorrect-schema", "" };
        yield return new object[] { "wrong-product", "" };
        yield return new object[] { "uppercase-root-id", "" };
        yield return new object[] { "zero-root-version", "" };
        yield return new object[] { "short-root-version", "" };
        yield return new object[] { "wrong-role", "" };
        yield return new object[] { "wrong-algorithm", "" };
        yield return new object[] { "zero-keys", "" };
        yield return new object[] { "nine-keys", "" };
        yield return new object[] { "truncated-key-list", "" };
        yield return new object[] { "reordered-keys", "" };
        yield return new object[] { "duplicate-keys", "" };
        yield return new object[] { "key-list-trailing-byte", "" };
        yield return new object[] { "zero-threshold", "" };
        yield return new object[] { "excess-threshold", "" };
        yield return new object[] { "invalid-expiration", "" };
        yield return new object[] { "unknown-rotation", "" };
        yield return new object[] { "invalid-optional-marker", "" };
        yield return new object[] { "missing-revocation", "" };
        yield return new object[] { "short-revocation", "" };
    }

    [Theory]
    [MemberData(nameof(RejectedReferenceCases))]
    public void AcceptedP91AdversarialWireIsRejected(
        string scenario, string hex)
    {
        Assert.False(string.IsNullOrEmpty(scenario));

        byte[] candidate = Convert.FromHexString(hex);

        Assert.False(
            new TruthDoctorV3CanonicalRootManifestReferenceDecoder()
                .IsCanonicalReference(candidate));
    }

    [Fact]
    public void OriginalKnownAnswerRemainsCanonical()
    {
        byte[] sample = Convert.FromHexString(KnownAnswerHex);

        Assert.True(
            new TruthDoctorV3CanonicalRootManifestReferenceDecoder()
                .IsCanonicalReference(sample));
    }

    [Fact]
    public void MalformedInputRemainsUnchanged()
    {
        byte[] invalid = Convert.FromHexString(KnownAnswerHex)
            .Concat(new byte[] { 0x00 }).ToArray();
        byte[] before = invalid.ToArray();

        Assert.False(
            new TruthDoctorV3CanonicalRootManifestReferenceDecoder()
                .IsCanonicalReference(invalid));

        Assert.Equal(before, invalid);
    }

    [Fact]
    public void RepeatedMalformedInputDeterministicallyRejects()
    {
        byte[] invalid = Convert.FromHexString(KnownAnswerHex);
        invalid[0] ^= 0x01;

        var decoder =
            new TruthDoctorV3CanonicalRootManifestReferenceDecoder();

        for (int i = 0; i < 8; i++)
        {
            Assert.False(decoder.IsCanonicalReference(invalid));
        }
    }
}
